  input wire clk, reset, btn;
  output reg wea;
  output reg [3:0] addra;

  localparam [1:0]
  idle = 2'b00,
  leer = 2'b01,
  fin  = 2'b10;

  reg [1:0] state_reg;
  reg [3:0] counter;

  always@(posedge clk, posedge reset)
