        if(btn==1'b1)begin
          state_reg<=leer;
        end

      leer:
        begin
          wea<=0;
          counter<=counter+1'b1;
          state_reg<=fin;
        end

      fin:begin

        addra<=addra+1'b1;
        if(counter==4'b1111)begin
          counter<=0;
        end
        state_reg<=idle;
      end	

    endcase
  end

endmodule

